using System.Net;
using System.Runtime.InteropServices;
using System.Security.Claims;
using System.Text;
using System.Text.Json;
using WebPush;

public static class DemoDevices
{
    static bool Staff(ClaimsPrincipal u)=>new[]{"owner","manager","cashier"}.Contains(u.FindFirstValue(ClaimTypes.Role)??"");
    public static void MapDeviceEndpoints(this WebApplication app)
    {
        app.MapGet("/api/printer/settings",async(ClaimsPrincipal u)=>{if(!Staff(u))return Results.Forbid();await using var c=DemoDb.Open();var r=(await DemoDb.Rows(c,"SELECT PrinterName,AutoPrint,OpenCashDrawer FROM PrinterSettings LIMIT 1")).FirstOrDefault();return Results.Ok(r is null?new{printerName="",autoPrint=false,openCashDrawer=false}:new{printerName=r.S("PrinterName"),autoPrint=r.B("AutoPrint"),openCashDrawer=r.B("OpenCashDrawer")});});
        app.MapPut("/api/printer/settings",async(PrinterSettingsInput x,ClaimsPrincipal u)=>{if(!Staff(u))return Results.Forbid();await using var c=DemoDb.Open();await DemoDb.Exec(c,"INSERT INTO PrinterSettings(StoreId,PrinterName,AutoPrint,OpenCashDrawer,UpdatedAt)VALUES((SELECT Id FROM Stores LIMIT 1),@n,@a,@d,@now) ON CONFLICT(StoreId) DO UPDATE SET PrinterName=excluded.PrinterName,AutoPrint=excluded.AutoPrint,OpenCashDrawer=excluded.OpenCashDrawer,UpdatedAt=excluded.UpdatedAt",("@n",x.PrinterName?.Trim()??""),("@a",x.AutoPrint),("@d",x.OpenCashDrawer),("@now",DemoDb.Now));return Results.Ok(x);});
        app.MapPost("/api/printer/test",async(ClaimsPrincipal u)=>{if(!Staff(u))return Results.Forbid();var s=await PrinterSetting();try{RawPrinter.Send(s.Name,RawPrinter.Receipt("ROAST & ROOT\nIN THU MAY IN THANH CONG\n"+DateTime.Now.ToString("dd/MM/yyyy HH:mm"),s.Drawer));return Results.Ok(new{ok=true});}catch(Exception e){return Results.BadRequest(new{error=e.Message});}});
        app.MapPost("/api/printer/open-drawer",async(ClaimsPrincipal u)=>{if(!Staff(u))return Results.Forbid();var s=await PrinterSetting();try{RawPrinter.Send(s.Name,RawPrinter.Drawer());return Results.Ok(new{ok=true});}catch(Exception e){return Results.BadRequest(new{error=e.Message});}});
        app.MapPost("/api/orders/{id:guid}/print",async(Guid id,ClaimsPrincipal u)=>{if(!Staff(u))return Results.Forbid();await using var c=DemoDb.Open();var o=(await DemoDb.Rows(c,"SELECT o.OrderNumber,COALESCE(t.Code,'Mang di') TableName,o.OpenedAt,o.Subtotal,o.Discount+o.LoyaltyDiscount Discount,o.Total FROM Orders o LEFT JOIN DiningTables t ON t.Id=o.TableId WHERE o.Id=@id",("@id",id))).FirstOrDefault();if(o is null)return Results.NotFound(new{error="Không tìm thấy đơn."});var items=await DemoDb.Rows(c,"SELECT i.Quantity,i.ProductName,i.UnitPrice+COALESCE((SELECT SUM(Price*Quantity) FROM OrderItemToppings WHERE OrderItemId=i.Id),0) Price,COALESCE(i.Note,'') Note FROM OrderItems i WHERE OrderId=@id AND Status<>'cancelled' ORDER BY CreatedAt",("@id",id));var text=RawPrinter.Header(o.L("OrderNumber"),o.S("TableName"),o.D("OpenedAt"));foreach(var i in items)text+=RawPrinter.Item(i.I("Quantity"),i.S("ProductName"),i.I("Price"),i.S("Note"));text+=RawPrinter.Footer(o.I("Subtotal"),o.I("Discount"),o.I("Total"));var s=await PrinterSetting();try{RawPrinter.Send(s.Name,RawPrinter.Receipt(text,false));return Results.Ok(new{ok=true});}catch(Exception e){return Results.BadRequest(new{error=e.Message});}});

        app.MapGet("/api/push/public-key",async()=>Results.Ok(new{publicKey=(await Keys()).Public}));
        app.MapPost("/api/push/subscribe",async(PushSubscriptionInput x,ClaimsPrincipal u)=>{if(string.IsNullOrWhiteSpace(x.Endpoint)||string.IsNullOrWhiteSpace(x.P256dh)||string.IsNullOrWhiteSpace(x.Auth))return Results.BadRequest(new{error="Dữ liệu đăng ký thông báo không hợp lệ."});await using var c=DemoDb.Open();await DemoDb.Exec(c,"INSERT INTO PushSubscriptions(Id,UserId,Endpoint,P256dh,Auth,CreatedAt)VALUES(@id,@u,@e,@p,@a,@now) ON CONFLICT(Endpoint) DO UPDATE SET UserId=excluded.UserId,P256dh=excluded.P256dh,Auth=excluded.Auth",("@id",DemoDb.Id()),("@u",u.FindFirstValue(ClaimTypes.NameIdentifier)),("@e",x.Endpoint),("@p",x.P256dh),("@a",x.Auth),("@now",DemoDb.Now));return Results.Ok(new{ok=true});});
        app.MapPost("/api/push/unsubscribe",async(PushUnsubscribeInput x,ClaimsPrincipal u)=>{await using var c=DemoDb.Open();await DemoDb.Exec(c,"DELETE FROM PushSubscriptions WHERE Endpoint=@e AND UserId=@u",("@e",x.Endpoint),("@u",u.FindFirstValue(ClaimTypes.NameIdentifier)));return Results.NoContent();});
    }
    public static async Task SendReady(string orderId)
    {
        await using var c=DemoDb.Open();var o=(await DemoDb.Rows(c,"SELECT o.OrderNumber,COALESCE(t.Code,'Mang đi') TableName,o.OpenedBy FROM Orders o LEFT JOIN DiningTables t ON t.Id=o.TableId WHERE o.Id=@id",("@id",orderId))).FirstOrDefault();if(o is null)return;var subs=await DemoDb.Rows(c,"SELECT s.Id,s.Endpoint,s.P256dh,s.Auth FROM PushSubscriptions s JOIN Users u ON u.Id=s.UserId WHERE u.IsActive=1 AND (u.Role='server' OR s.UserId=@opened)",("@opened",o.S("OpenedBy")));var keys=await Keys();using var client=new WebPushClient();var payload=JsonSerializer.Serialize(new{title="Món đã sẵn sàng",body=$"{o.S("TableName")} · đơn #{o.L("OrderNumber")}: đến quầy nhận món",url="/"});foreach(var s in subs){try{await client.SendNotificationAsync(new PushSubscription(s.S("Endpoint"),s.S("P256dh"),s.S("Auth")),payload,new VapidDetails("mailto:admin@roastandroot.local",keys.Public,keys.Private));}catch(WebPushException e)when(e.StatusCode is HttpStatusCode.Gone or HttpStatusCode.NotFound){await DemoDb.Exec(c,"DELETE FROM PushSubscriptions WHERE Id=@id",("@id",s.S("Id")));}catch{}}
    }
    static async Task<(string Public,string Private)> Keys(){await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT Key,Value FROM SystemSettings WHERE Key IN ('VapidPublicKey','VapidPrivateKey')");var d=rs.ToDictionary(r=>r.S("Key"),r=>r.S("Value"));if(d.TryGetValue("VapidPublicKey",out var pub)&&d.TryGetValue("VapidPrivateKey",out var priv))return(pub,priv);var k=VapidHelper.GenerateVapidKeys();await DemoDb.Exec(c,"INSERT INTO SystemSettings(Key,Value,UpdatedAt)VALUES('VapidPublicKey',@pub,@now),('VapidPrivateKey',@priv,@now) ON CONFLICT(Key) DO UPDATE SET Value=excluded.Value,UpdatedAt=excluded.UpdatedAt",("@pub",k.PublicKey),("@priv",k.PrivateKey),("@now",DemoDb.Now));return(k.PublicKey,k.PrivateKey);}
    static async Task<(string Name,bool Drawer)> PrinterSetting(){await using var c=DemoDb.Open();var r=(await DemoDb.Rows(c,"SELECT PrinterName,OpenCashDrawer FROM PrinterSettings LIMIT 1")).FirstOrDefault();return r is null?("",false):(r.S("PrinterName"),r.B("OpenCashDrawer"));}
}

static class RawPrinter
{
    [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]sealed class DocInfo{[MarshalAs(UnmanagedType.LPWStr)]public string DocName="CoffeeOS Receipt";[MarshalAs(UnmanagedType.LPWStr)]public string? OutputFile;[MarshalAs(UnmanagedType.LPWStr)]public string DataType="RAW";}
    [DllImport("winspool.drv",SetLastError=true,CharSet=CharSet.Unicode)]static extern bool OpenPrinter(string n,out IntPtr p,IntPtr d);[DllImport("winspool.drv",SetLastError=true)]static extern bool ClosePrinter(IntPtr p);[DllImport("winspool.drv",SetLastError=true,CharSet=CharSet.Unicode)]static extern bool StartDocPrinter(IntPtr p,int l,[In]DocInfo i);[DllImport("winspool.drv",SetLastError=true)]static extern bool EndDocPrinter(IntPtr p);[DllImport("winspool.drv",SetLastError=true)]static extern bool StartPagePrinter(IntPtr p);[DllImport("winspool.drv",SetLastError=true)]static extern bool EndPagePrinter(IntPtr p);[DllImport("winspool.drv",SetLastError=true)]static extern bool WritePrinter(IntPtr p,byte[] b,int c,out int w);
    public static void Send(string name,byte[] bytes){if(string.IsNullOrWhiteSpace(name))throw new InvalidOperationException("Chưa cấu hình tên máy in.");if(!OpenPrinter(name,out var h,IntPtr.Zero))throw new InvalidOperationException($"Không mở được máy in '{name}'.");try{if(!StartDocPrinter(h,1,new DocInfo()))throw new InvalidOperationException("Không tạo được lệnh in.");StartPagePrinter(h);if(!WritePrinter(h,bytes,bytes.Length,out var written)||written!=bytes.Length)throw new InvalidOperationException("Máy in không nhận đủ dữ liệu.");EndPagePrinter(h);EndDocPrinter(h);}finally{ClosePrinter(h);}}
    public static byte[] Receipt(string text,bool drawer){Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);var b=new List<byte>{0x1b,0x40};if(drawer)b.AddRange(Drawer());b.AddRange(Encoding.GetEncoding(1258).GetBytes(text.Replace("đ","d")+"\n\n\n"));b.AddRange(new byte[]{0x1d,0x56,0x41,0});return b.ToArray();}public static byte[] Drawer()=>new byte[]{0x1b,0x40,0x1b,0x70,0,0x19,0xfa};
    const int W=42;static string C(string x)=>x.Length>=W?x[..W]:new string(' ',(W-x.Length)/2)+x;static string Clip(string x,int w)=>x.Length<=w?x:x[..Math.Max(1,w-1)]+"~";static string A(string l,int a)=>l+new string(' ',Math.Max(1,W-l.Length-$"{a:N0}d".Length))+$"{a:N0}d";
    public static string Header(long no,string table,DateTime opened)=>$"{new string('=',W)}\n{C("ROAST & ROOT")}\n{C("COFFEE OPERATING SYSTEM")}\n{new string('=',W)}\nHOA DON THANH TOAN\nMa HD: HD{no:000000}\nBan: {table}\nNgay: {opened.ToLocalTime():dd/MM/yyyy HH:mm}\n{new string('-',W)}\n{"Ten mon",-18}{"SL",3}{"Don gia",10}{"T.Tien",11}\n{new string('-',W)}\n";
    public static string Item(int q,string n,int p,string note)=>$"{Clip(n,18),-18}{q,3}{p,10:N0}{p*q,11:N0}\n"+(string.IsNullOrWhiteSpace(note)?"":$"  > {Clip(note,W-4)}\n");public static string Footer(int sub,int discount,int total)=>$"{new string('-',W)}\n{A("Tam tinh:",sub)}\n"+(discount>0?A("Giam gia / diem:",-discount)+"\n":"")+$"{new string('-',W)}\n{A("TONG CONG:",total)}\n{new string('-',W)}\n\n{C("Cam on & hen gap lai Quy khach!")}\n{new string('=',W)}";
}
record PrinterSettingsInput(string? PrinterName,bool AutoPrint,bool OpenCashDrawer);
record PushSubscriptionInput(string Endpoint,string P256dh,string Auth);
record PushUnsubscribeInput(string Endpoint);
